```ts
import { Util, KickLang } from '../'

export interface Code74kEntry {
  id: string
  conversations: Conversation[]
}

export interface Conversation {
  from: 'human' | 'gpt'
  value: string
}

export class Code74k extends Util {
  static readonly id = '[ code-74k ]'
  static readonly unit = 'entry'
  static readonly data = 'Code74k.json'
  static readonly types = {
    Code74kEntry,
    Conversation,
  }
}

export const Code74kQuery = KickLang.define(Code74k)
```

